import { PerspectiveCamera } from '@react-three/drei'
import { Canvas, useFrame, useThree } from '@react-three/fiber'
import { Suspense, useMemo, useRef } from 'react'
import {
  BackSide,
  Color,
  NoToneMapping,
  Vector2,
  Vector3,
  Vector4,
  type ShaderMaterial,
} from 'three'

import { background, camera as cameraConfig, DEG, easeOutSine, eye, eyeGroup, lens } from './config'
import {
  backgroundFragment,
  backgroundVertex,
  eyeFragment,
  eyeVertex,
  lensFragment,
  lensVertex,
} from './shaders/landing'
import { useGeometry } from './useGeometry'
import { useTexture } from './useTexture'

/**
 * Replays one of the engine's shader tweens: `uTransition` 0 -> to over
 * `duration`, easeOutSine, after `delay`. Takes elapsed ms, returns the value.
 */
function transitionAt(
  elapsed: number,
  { to, duration, delay }: { to: number; duration: number; delay: number }
) {
  const t = elapsed - delay
  return easeOutSine(t <= 0 ? 0 : Math.min(1, t / duration)) * to
}

function BackgroundSphere() {
  const ramp = useTexture(background.colorRamp, { color: true })
  const materialRef = useRef<ShaderMaterial>(null)

  const uniforms = useMemo(
    () => ({
      time: { value: 0 },
      tColorRamp: { value: ramp },
      uColorRange: { value: new Vector2(...background.uniforms.uColorRange) },
      uBrightness: { value: background.uniforms.uBrightness },
      uNoiseScale: { value: background.uniforms.uNoiseScale },
      uNoiseSpeed: { value: background.uniforms.uNoiseSpeed },
      uSaturation: { value: background.uniforms.uSaturation },
      uContrastAdjust: { value: background.uniforms.uContrastAdjust },
    }),
    [ramp]
  )

  useFrame(({ clock }) => {
    const material = materialRef.current
    if (material) material.uniforms.time.value = clock.elapsedTime
  })

  return (
    <mesh scale={background.scale} renderOrder={0}>
      <sphereGeometry args={[1, 16, 16]} />
      <shaderMaterial
        ref={materialRef}
        vertexShader={backgroundVertex}
        fragmentShader={backgroundFragment}
        uniforms={uniforms}
        side={BackSide}
        depthWrite={false}
      />
    </mesh>
  )
}

function Eye() {
  const geometry = useGeometry(eye.geometry)
  const map = useTexture(eye.map, { repeat: true })
  const materialRef = useRef<ShaderMaterial>(null)

  const uniforms = useMemo(
    () => ({
      time: { value: 0 },
      tMap: { value: map },
      uColor: { value: new Color(eye.uniforms.uColor) },
      uTile: { value: new Vector2(...eye.uniforms.uTile) },
      uPinchRange: { value: new Vector2(...eye.uniforms.uPinchRange) },
      uFadeRange: { value: new Vector4(...eye.uniforms.uFadeRange) },
      uBands1: { value: new Vector4(...eye.uniforms.uBands1) },
      uBands2: { value: new Vector4(...eye.uniforms.uBands2) },
      uTransition: { value: 0 },
    }),
    [map]
  )

  useFrame(({ clock }) => {
    const material = materialRef.current
    if (!material) return
    material.uniforms.time.value = clock.elapsedTime
    material.uniforms.uTransition.value = transitionAt(clock.elapsedTime * 1000, eye.transition)
  })

  return (
    <mesh
      geometry={geometry}
      position={eye.position}
      rotation={[eye.rotation[0] * DEG, eye.rotation[1] * DEG, eye.rotation[2] * DEG]}
      scale={eye.scale}
      renderOrder={eye.renderOrder}
    >
      <shaderMaterial
        ref={materialRef}
        vertexShader={eyeVertex}
        fragmentShader={eyeFragment}
        uniforms={uniforms}
        transparent
        depthWrite={false}
      />
    </mesh>
  )
}

function Lens() {
  const geometry = useGeometry(lens.geometry)
  const matcap = useTexture(lens.matcap, { color: true })
  const materialRef = useRef<ShaderMaterial>(null)

  const uniforms = useMemo(
    () => ({
      tMatcap: { value: matcap },
      uColor: { value: new Color(lens.uniforms.uColor) },
      uReflectOffset: { value: new Vector3(...lens.uniforms.uReflectOffset) },
      uTransition: { value: 0 },
    }),
    [matcap]
  )

  useFrame(({ clock }) => {
    const material = materialRef.current
    if (!material) return
    material.uniforms.uTransition.value = transitionAt(clock.elapsedTime * 1000, lens.transition)
  })

  return (
    <mesh
      geometry={geometry}
      position={lens.position}
      scale={lens.scale}
      renderOrder={lens.renderOrder}
    >
      <shaderMaterial
        ref={materialRef}
        vertexShader={lensVertex}
        fragmentShader={lensFragment}
        uniforms={uniforms}
        transparent
        depthWrite={false}
      />
    </mesh>
  )
}

/**
 * Camera placement plus the editor's aspect-driven FOV, which widens the lens
 * on portrait viewports. The level's lookAt sits straight down -Z from the
 * camera, so the default orientation already matches it.
 */
function CameraRig() {
  const size = useThree((state) => state.size)

  return (
    <PerspectiveCamera
      makeDefault
      position={cameraConfig.position}
      fov={cameraConfig.fovForAspect(size.width / size.height)}
      near={cameraConfig.near}
      far={cameraConfig.far}
    />
  )
}

/**
 * The landing scene, rebuilt on react-three-fiber.
 *
 * Ported so far: background sphere, eye, lens. Still on the legacy engine: the
 * 65k-particle spline system (`landingeyesplines`), the mouse-fluid
 * displacement those feed off, the logo/tagline text meshes, and the engine's
 * post stack — which is why this reads sharper than the live home.
 */
export function Scene() {
  return (
    <Canvas
      style={{ position: 'fixed', inset: 0 }}
      dpr={[1, 2]}
      // The engine wrote straight to the backbuffer; no filmic curve on top.
      gl={{ antialias: true, toneMapping: NoToneMapping }}
    >
      <CameraRig />
      <Suspense fallback={null}>
        <BackgroundSphere />
        <group
          position={eyeGroup.position}
          rotation={[
            eyeGroup.rotation[0] * DEG,
            eyeGroup.rotation[1] * DEG,
            eyeGroup.rotation[2] * DEG,
          ]}
          scale={eyeGroup.scale}
        >
          <Eye />
          <Lens />
        </group>
      </Suspense>
    </Canvas>
  )
}
